#include <flint/nmod_mat.h>
#include <fstream>
#include <iostream>
#include <vector>
#include <stdexcept>
using namespace std;int main(int argc,char**argv){if(argc!=2)return 2;ifstream in(argv[1]);long nr,nq,nl,nn;in>>nr>>nq>>nl>>nn;nmod_mat_t M,Q,T,S;nmod_mat_init(M,nr,nq+nl,32003);nmod_mat_init(Q,nr,nq,32003);nmod_mat_init(T,nq+nl,nr,32003);for(long k=0;k<nn;k++){long i,j,c;in>>i>>j>>c;nmod_mat_entry(M,i,j)=c;if(j<nq)nmod_mat_entry(Q,i,j)=c;}long rq=nmod_mat_rank(Q);nmod_mat_transpose(T,M);long rank=nmod_mat_rref(T);vector<long> rows,cols;for(long i=0;i<rank;i++){long j=0;while(j<nr&&!nmod_mat_entry(T,i,j))j++;if(j==nr)throw runtime_error("pivot");rows.push_back(j);}for(long j=0;j<nq+nl;j++){bool nz=false;for(long i=0;i<nr;i++)if(nmod_mat_entry(M,i,j)){nz=true;break;}if(nz)cols.push_back(j);}nmod_mat_t U;nmod_mat_init(U,rank,nq+nl,32003);for(long i=0;i<rank;i++)for(long j=0;j<nq+nl;j++)nmod_mat_entry(U,i,j)=nmod_mat_entry(M,rows[i],j);long check=nmod_mat_rref(U);if(check!=rank)throw runtime_error("rowbasis");cols.clear();for(long i=0;i<rank;i++){long j=0;while(j<nq+nl&&!nmod_mat_entry(U,i,j))j++;cols.push_back(j);}nmod_mat_clear(U);nmod_mat_init(S,rank,rank,32003);for(long i=0;i<rank;i++)for(long j=0;j<rank;j++)nmod_mat_entry(S,i,j)=nmod_mat_entry(M,rows[i],cols[j]);ulong det=nmod_mat_det(S);if(!det)throw runtime_error("minorzero");cout<<"QUADRANK "<<rq<<" TOTALRANK "<<rank<<" DET "<<det<<"\nROWS";for(long i:rows)cout<<" "<<i;cout<<"\nCOLS";for(long j:cols)cout<<" "<<j;cout<<"\n";nmod_mat_clear(M);nmod_mat_clear(Q);nmod_mat_clear(T);nmod_mat_clear(S);return 0;}
